def balance_parentheses_and_quotes(text):
    """
    Verifica si los parentesis, corchetes y llaves del texto estan correctamente balanceados y anidados.
    """
    stack = []
    opening = {'(', '[', '{'}
    closing = {')', ']', '}'}

    for char in text:
        if char in opening:
            stack.append(char)
        elif char in closing:
            if not stack:
                return False
            last_opening = stack.pop()
            if (char == ')' and last_opening != '(') or (char == ']' and last_opening != '[') or (char == '}' and last_opening != '{'):
                return False

    return len(stack) == 0

