def median(nums):
    if len(nums) < 2:
        return None
    nums_sorted = sorted(nums)
    n = len(nums_sorted)
    mid = n // 2
    if n % 2 == 0:
        left = nums_sorted[mid - 1]
        right = nums_sorted[mid]
    else:
        left = nums_sorted[mid]
        right = nums_sorted[mid + 1]
    return (left + right) / 2

