def count_islands(grid):
    if not grid:
        return 0

    rows = len(grid)
    cols = len(grid[0])
    count = 0

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1:
                # Start a new island
                count += 1
                # DFS to mark all connected 1s
                stack = [(i, j)]
                while stack:
                    x, y = stack.pop()
                    if 0 <= x < rows and 0 <= y < cols and grid[x][y] == 1:
                        grid[x][y] = 0  # mark as visited
                        # Check neighbors
                        stack.append((x+1, y))
                        stack.append((x-1, y))
                        stack.append((x, y+1))
                        stack.append((x, y-1))

    return count

def levenshtein_distance(a, b):
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            cost = 0 if a[i - 1] == b[j - 1] else 1
            dp[i][j] = min(
                dp[i - 1][j] + 1,      # deletion
                dp[i][j - 1] + 1,      # insertion
                dp[i - 1][j - 1] + cost  # substitution
            )
    return dp[m][n]

def validar_password(password):
    # Check length
    if len(password) < 8:
        return False
    # Check uppercase
    if not any(c.isupper() for c in password):
        return False
    # Check lowercase
    if not any(c.islower() for c in password):
        return False
    # Check digit
    if not any(c.isdigit() for c in password):
        return False
    # Check non-alphanumeric
    if not any(not c.isalnum() for c in password):
        return False
    return True

def convert_to_base(n, base):
    digits = "0123456789abcdef"
    if n == 0:
        return "0"
    result = ""
    while n > 0:
        remainder = n % base
        result = digits[remainder] + result
        n //= base
    return result

