def capitalize_words(sentence):
    words = sentence.split()
    if not words:
        return ""
    result = []
    for i, word in enumerate(words):
        if i == 0:
            result.append(word.capitalize())
        else:
            if word.startswith('de'):
                result.append(word[2:].lower())
            elif word.startswith('del'):
                result.append(word[3:].lower())
            elif word.startswith('la'):
                result.append(word[2:].lower())
            elif word.startswith('las'):
                result.append(word[2:].lower())
            elif word.startswith('el'):
                result.append(word[1:].lower())
            elif word.startswith('los'):
                result.append(word[2:].lower())
            else:
                result.append(word.lower())
    return ' '.join(result)

